    a_intervals = [x for x in a if x[0] < x[1]]
    b_intervals = [x for x in b if x[0] < x[1]]

    if not a_intervals:
        return []

    # Create events for a: (position, type) where type 1 = start, -1 = end
    events = []
    for start, end in a_intervals:
        events.append((start, 1))
        events.append((end, -1))

    # Sort events by position, with starts before ends at same position
    events.sort(key=lambda x: (x[0], -x[1]))

    # Merge overlapping intervals in a
    merged_a = []
    active = 0
    last_pos = None

    for pos, event_type in events:
        if active > 0 and pos > last_pos and active == 0:
            merged_a.append([last_pos, pos])
        if event_type == 1:
            if active == 0:
                last_pos = pos
            active += 1
        else:
            active -= 1

    if active > 0:
        merged_a.append([last_pos, events[-1][0]])

    # Rebuild merged_a correctly
    merged_a = []
    active = 0
    start_pos = None

    for pos, event_type in events:
        if event_type == 1:
            if active == 0:
                start_pos = pos
            active += 1
        else:
            active -= 1
            if active == 0:
                merged_a.append([start_pos, pos])

    if not merged_a:
        return []

    # Now subtract b from merged_a
    result = merged_a[:]

    for b_start, b_end in b_intervals:
        new_result = []
        for a_start, a_end in result:
            # Check if b interval overlaps with a interval
            if b_end <= a_start or b_start >= a_end:
                # No overlap
                new_result.append([a_start, a_end])
            else:
                # There is overlap, split a interval
                if a_start < b_start:
                    new_result.append([a_start, b_start])
                if a_end > b_end:
                    new_result.append([b_end, a_end])
        result = new_result

    # Merge touching intervals
    if not result:
        return []

    result.sort()
    merged = [result[0]]

    for current in result[1:]:
        if merged[-1][1] == current[0]:
            # Touching, merge them
            merged[-1][1] = current[1]
        else:
            merged.append(current)

    return merged

